//! Persistent topological references (ADR 0003), e.g.
//! `edge(Extrude1/cap(end), Extrude1/side(Sketch1/l3))`.
//!
//! References are names derived from how entities were created, never indices.

use crate::cursor::{Cursor, ParseError};
use std::fmt;

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum CapSide {
    Start,
    End,
}

/// How a face was generated by its feature.
#[derive(Debug, Clone, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum FaceKey {
    /// Lateral face swept from a sketch entity.
    Side { sketch: String, entity: String },
    /// Start/end cap of a sweep. `region` is the profile region's identifying entity
    /// when the sketch has several regions.
    Cap { side: CapSide, region: Option<String> },
    /// Blend face created by a fillet/chamfer on an edge.
    Blend(Box<EdgeRef>),
    /// Face of an imported body, by its stable import index.
    Imported(u32),
    /// Inner wall face made by a shell from the named face (`Shell1/inner(<face>)`).
    Inner(Box<FaceRef>),
    /// Mirror image of the named face (`Mirror1/mirror(<face>)`).
    Mirror(Box<FaceRef>),
    /// Face of the moved copy made by a `move` with `copy: true`
    /// (`Move1/copy(<face>)`).
    Copy(Box<FaceRef>),
    /// Face of the body a `component` brings in, named by its face in the component's own
    /// document (`Wheel/part(Extrude1/cap(end))`). The inner name refers to that document,
    /// not to this one's features.
    Part(Box<FaceRef>),
    /// Face of pattern instance `k` (1-based; 0 is the source) copied from the named
    /// face (`Pattern1/instance(2, <face>)`).
    Instance { k: u32, face: Box<FaceRef> },
    /// A face of one hole of a `hole` feature (`Hole1/wall(p5)`): `at` is the id of the
    /// sketch point the hole sits at (`p5`, `p5_2` for a pattern copy) or `e1`, `e2`, ...
    /// for the explicit points of the feature, in list order.
    Hole { part: HolePart, at: String },
}

/// Which face of a hole (ADR 0019).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum HolePart {
    /// The tool's disc in the mouth plane. It lies in the face the hole starts on, so it
    /// never survives as a face of its own.
    Top,
    /// The cylindrical wall of the full-diameter part.
    Wall,
    /// The bottom: the drill-point cone, or the flat end of a hole that ends in a plane.
    Floor,
    /// The wall of a counterbore.
    CboreWall,
    /// The flat step between a counterbore and the hole.
    CboreFloor,
    /// The cone of a countersink.
    Csink,
}

impl HolePart {
    pub const ALL: [HolePart; 6] =
        [HolePart::Top, HolePart::Wall, HolePart::Floor, HolePart::CboreWall, HolePart::CboreFloor, HolePart::Csink];

    pub fn keyword(self) -> &'static str {
        match self {
            HolePart::Top => "top",
            HolePart::Wall => "wall",
            HolePart::Floor => "floor",
            HolePart::CboreWall => "cbore_wall",
            HolePart::CboreFloor => "cbore_floor",
            HolePart::Csink => "csink",
        }
    }

    pub fn from_keyword(s: &str) -> Option<Self> {
        Self::ALL.into_iter().find(|p| p.keyword() == s)
    }
}

/// A named face: `<feature>/<key>[#k]`.
#[derive(Debug, Clone, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub struct FaceRef {
    pub feature: String,
    pub key: FaceKey,
    /// Disambiguates split faces (1-based, ordered by geometric key).
    pub index: Option<u32>,
}

/// A named edge: the faces it bounds (sorted), plus a disambiguator.
#[derive(Debug, Clone, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub struct EdgeRef {
    pub faces: Vec<FaceRef>,
    pub index: Option<u32>,
}

impl FaceRef {
    pub fn new(feature: impl Into<String>, key: FaceKey) -> Self {
        FaceRef { feature: feature.into(), key, index: None }
    }

    /// Calls `f` with every feature name mentioned in the reference.
    pub fn features(&self, f: &mut dyn FnMut(&str)) {
        f(&self.feature);
        match &self.key {
            FaceKey::Side { sketch, .. } => f(sketch),
            FaceKey::Blend(e) => e.features(f),
            FaceKey::Inner(r) | FaceKey::Mirror(r) | FaceKey::Copy(r) | FaceKey::Instance { face: r, .. } => {
                r.features(f);
            }
            FaceKey::Cap { .. } | FaceKey::Imported(_) | FaceKey::Hole { .. } | FaceKey::Part(_) => {}
        }
    }

    /// Renames every occurrence of feature `from` to `to`.
    pub fn rename_feature(&mut self, from: &str, to: &str) {
        if self.feature == from {
            self.feature = to.to_string();
        }
        match &mut self.key {
            FaceKey::Side { sketch, .. } if sketch == from => *sketch = to.to_string(),
            FaceKey::Blend(e) => e.rename_feature(from, to),
            FaceKey::Inner(r) | FaceKey::Mirror(r) | FaceKey::Copy(r) | FaceKey::Instance { face: r, .. } => {
                r.rename_feature(from, to);
            }
            _ => {}
        }
    }

    pub fn parse(s: &str) -> Result<FaceRef, ParseError> {
        let mut c = Cursor::new(s, 1);
        let r = parse_face(&mut c)?;
        if !c.at_end() {
            return Err(c.err("unexpected text after reference"));
        }
        Ok(r)
    }
}

impl EdgeRef {
    /// Builds an edge reference with its faces in canonical (sorted) order.
    pub fn new(mut faces: Vec<FaceRef>, index: Option<u32>) -> Self {
        sort_faces(&mut faces);
        EdgeRef { faces, index }
    }

    pub fn features(&self, f: &mut dyn FnMut(&str)) {
        for face in &self.faces {
            face.features(f);
        }
    }

    pub fn rename_feature(&mut self, from: &str, to: &str) {
        for face in &mut self.faces {
            face.rename_feature(from, to);
        }
        sort_faces(&mut self.faces);
    }

    pub fn parse(s: &str) -> Result<EdgeRef, ParseError> {
        let mut c = Cursor::new(s, 1);
        let r = parse_edge(&mut c)?;
        if !c.at_end() {
            return Err(c.err("unexpected text after reference"));
        }
        Ok(r)
    }
}

/// Canonical face order inside an edge reference: by printed text, so it is predictable
/// for people reading and writing references.
fn sort_faces(faces: &mut Vec<FaceRef>) {
    faces.sort_by_cached_key(ToString::to_string);
    faces.dedup();
}

impl fmt::Display for FaceRef {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}/", self.feature)?;
        match &self.key {
            FaceKey::Side { sketch, entity } => write!(f, "side({sketch}/{entity})")?,
            FaceKey::Cap { side, region } => {
                let s = match side {
                    CapSide::Start => "start",
                    CapSide::End => "end",
                };
                match region {
                    Some(r) => write!(f, "cap({s}, {r})")?,
                    None => write!(f, "cap({s})")?,
                }
            }
            FaceKey::Blend(e) => write!(f, "blend({e})")?,
            FaceKey::Imported(i) => write!(f, "face({i})")?,
            FaceKey::Inner(r) => write!(f, "inner({r})")?,
            FaceKey::Mirror(r) => write!(f, "mirror({r})")?,
            FaceKey::Copy(r) => write!(f, "copy({r})")?,
            FaceKey::Part(r) => write!(f, "part({r})")?,
            FaceKey::Instance { k, face } => write!(f, "instance({k}, {face})")?,
            FaceKey::Hole { part, at } => write!(f, "{}({at})", part.keyword())?,
        }
        if let Some(i) = self.index {
            write!(f, "#{i}")?;
        }
        Ok(())
    }
}

impl fmt::Display for EdgeRef {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str("edge(")?;
        for (i, face) in self.faces.iter().enumerate() {
            if i > 0 {
                f.write_str(", ")?;
            }
            write!(f, "{face}")?;
        }
        f.write_str(")")?;
        if let Some(i) = self.index {
            write!(f, "#{i}")?;
        }
        Ok(())
    }
}

fn parse_index(c: &mut Cursor<'_>) -> Result<Option<u32>, ParseError> {
    if c.peek() == Some('#') {
        // `#` directly after a reference is a disambiguator, not a comment.
        c.pos += 1;
        let i = c.uint()?;
        if i == 0 {
            return Err(c.err("disambiguation index starts at 1"));
        }
        return Ok(Some(i));
    }
    Ok(None)
}

pub(crate) fn parse_face(c: &mut Cursor<'_>) -> Result<FaceRef, ParseError> {
    c.enter()?;
    let feature = c.ident()?.to_string();
    c.expect('/')?;
    let kind = c.ident()?;
    c.expect('(')?;
    let key = match kind {
        k if HolePart::from_keyword(k).is_some() => {
            let part = HolePart::from_keyword(k).unwrap_or(HolePart::Wall);
            FaceKey::Hole { part, at: c.ident()?.to_string() }
        }
        "side" => {
            let sketch = c.ident()?.to_string();
            c.expect('/')?;
            let entity = c.ident()?.to_string();
            FaceKey::Side { sketch, entity }
        }
        "cap" => {
            let side = match c.ident()? {
                "start" => CapSide::Start,
                "end" => CapSide::End,
                other => return Err(c.err(format!("cap side must be 'start' or 'end', not '{other}'"))),
            };
            let region = if c.eat(',') { Some(c.ident()?.to_string()) } else { None };
            FaceKey::Cap { side, region }
        }
        "blend" => FaceKey::Blend(Box::new(parse_edge(c)?)),
        "face" => FaceKey::Imported(c.uint()?),
        "inner" => FaceKey::Inner(Box::new(parse_face(c)?)),
        "mirror" => FaceKey::Mirror(Box::new(parse_face(c)?)),
        "copy" => FaceKey::Copy(Box::new(parse_face(c)?)),
        "part" => FaceKey::Part(Box::new(parse_face(c)?)),
        "instance" => {
            let k = c.uint()?;
            if k == 0 {
                return Err(c.err("pattern instances are numbered from 1"));
            }
            c.expect(',')?;
            FaceKey::Instance { k, face: Box::new(parse_face(c)?) }
        }
        other => {
            return Err(c.err_hint(
                format!("unknown face kind '{other}'"),
                "use side(...), cap(start|end), blend(edge(...)), inner(<face>), mirror(<face>), copy(<face>), part(<face>), instance(k, <face>), face(N) or a hole face such as wall(p5)",
            ));
        }
    };
    c.expect(')')?;
    let index = parse_index(c)?;
    c.leave();
    Ok(FaceRef { feature, key, index })
}

pub(crate) fn parse_edge(c: &mut Cursor<'_>) -> Result<EdgeRef, ParseError> {
    c.enter()?;
    if !c.eat_kw("edge") {
        return Err(c.err_hint("expected an edge reference", "edge(<face>, <face>)"));
    }
    c.expect('(')?;
    let mut faces = vec![parse_face(c)?];
    while c.eat(',') {
        faces.push(parse_face(c)?);
        if faces.len() > 8 {
            return Err(c.err("an edge reference names at most 8 faces"));
        }
    }
    c.expect(')')?;
    let index = parse_index(c)?;
    c.leave();
    Ok(EdgeRef::new(faces, index))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn roundtrip() {
        for s in [
            "Extrude1/side(Sketch1/l3)",
            "Extrude1/cap(end)",
            "Extrude1/cap(start, l4)#2",
            "Fillet1/blend(edge(Extrude1/cap(end), Extrude1/side(Sketch1/l3)))",
            "Import1/face(12)",
            "Shell1/inner(Extrude1/cap(end))",
            "Shell1/inner(Extrude1/side(Sketch1/l3)#2)#1",
            "Mirror1/mirror(Extrude1/side(Sketch1/l3))",
            "Move1/copy(Extrude1/side(Sketch1/l3))",
            "Wheel/part(Extrude1/cap(end))",
            "Pattern1/instance(3, Extrude1/cap(start, l4)#2)",
            "Hole1/wall(p5)",
            "Hole1/cbore_floor(p5_2)#2",
            "Hole2/csink(e1)",
            "Pattern1/instance(1, Hole1/floor(p5))",
            "Pattern2/instance(1, Mirror1/mirror(Fillet1/blend(edge(Extrude1/cap(end), Extrude1/side(Sketch1/l3)))))",
        ] {
            let r = FaceRef::parse(s).unwrap();
            assert_eq!(r.to_string(), s);
        }
        let e = EdgeRef::parse("edge(Extrude1/side(Sketch1/l3), Extrude1/cap(end))#2").unwrap();
        // Faces are canonically sorted.
        assert_eq!(e.to_string(), "edge(Extrude1/cap(end), Extrude1/side(Sketch1/l3))#2");
    }

    #[test]
    fn features_and_rename() {
        let mut e = EdgeRef::parse("edge(Extrude1/side(Sketch1/l3), Extrude1/cap(end))").unwrap();
        let mut names = Vec::new();
        e.features(&mut |n| names.push(n.to_string()));
        assert!(names.contains(&"Sketch1".to_string()));
        e.rename_feature("Sketch1", "Base");
        assert!(e.to_string().contains("side(Base/l3)"));
        let mut m = FaceRef::parse("Mirror1/mirror(Extrude1/side(Sketch1/l3))").unwrap();
        let mut names = Vec::new();
        m.features(&mut |n| names.push(n.to_string()));
        assert_eq!(names, ["Mirror1", "Extrude1", "Sketch1"]);
        m.rename_feature("Extrude1", "Base");
        assert_eq!(m.to_string(), "Mirror1/mirror(Base/side(Sketch1/l3))");
    }

    #[test]
    fn errors() {
        assert!(FaceRef::parse("Extrude1/cap(middle)").is_err());
        assert!(FaceRef::parse("Extrude1/wat(1)").is_err());
        assert!(FaceRef::parse("Extrude1/face(1)#0").is_err());
        assert!(FaceRef::parse("P/instance(0, E/cap(end))").is_err());
        assert!(FaceRef::parse("P/instance(1 E/cap(end))").is_err());
        assert!(FaceRef::parse("P/mirror()").is_err());
        assert!(EdgeRef::parse("edge(Extrude1/cap(end)").is_err());
        let deep = format!("{}Extrude1/cap(end){}", "Fillet1/blend(edge(".repeat(20), ")))".repeat(20));
        assert!(FaceRef::parse(&deep).is_err());
    }
}
